export class QueryConstraint {
}
export class QueryCompositeFilterConstraint {
    constructor(type, ...queryCons) {
        this.type = type;
        this._queryCons = [...queryCons];
    }
}
export class QueryEndAtConstraint extends QueryConstraint {
    constructor(type, cons) {
        super();
        this.type = type;
        this.__cons = cons;
    }
}
export class QueryFieldFilterConstraint extends QueryConstraint {
    constructor(obj) {
        super();
        this.type = 'where';
        this.__cons = obj;
    }
}
export class QueryFieldJoinsConstraint extends QueryConstraint {
    constructor(obj) {
        super();
        this.type = 'join';
        this.__cons = obj;
    }
}
export class QueryLimitConstraint extends QueryConstraint {
    constructor(type, lim) {
        super();
        this.type = type;
        this.__cons = lim;
    }
}
export class QueryOrderByConstraint extends QueryConstraint {
    constructor(obj) {
        super();
        this.type = 'orderBy';
        this.__cons = obj;
    }
}
export class QueryStartAtConstraint extends QueryConstraint {
    constructor(type, cons) {
        super();
        this.type = type;
        this.__cons = cons;
    }
}
export class QueryVectorSearchConstraint extends QueryConstraint {
    constructor(cons) {
        super();
        this.type = 'vectorSearch';
        this.__cons = cons;
    }
}
